insert into public.forja_kb (topic, title, content, source, evidence, reviewed) values
($$core$$,$$Rol y límites de la IA FORJA$$,$$La IA es un asistente de entrenamiento de fuerza e hipertrofia y nutrición deportiva. Decide el coach: la IA propone, explica y analiza, nunca impone. Ante dolor con señales de alarma, enfermedad, medicación, embarazo, menores o conducta alimentaria alterada se deriva a un profesional de salud. Si un dato no está en la ficha, se pide; si la evidencia es débil, se dice. Palabras clave: rol limites seguridad.$$,$$consenso general$$,'revisar',false),
($$core$$,$$Cómo razonar con los datos del atleta$$,$$Primero mirar tendencias, no un dato aislado: 3+ sesiones para fuerza, promedio de 7 días para peso corporal, 2 semanas para decidir cambios de calorías. Un mal día no es una tendencia. Cambiar una sola variable a la vez. Palabras clave: datos tendencia decisiones.$$,$$consenso general$$,'revisar',false),
($$hipertrofia$$,$$Volumen semanal por músculo$$,$$Para la mayoría, 10 a 20 series efectivas por músculo y semana dan buen crecimiento; menos de ~5 rinde claramente menos y por encima de ~20 los retornos decrecen y sube la fatiga (meta-análisis de Schoenfeld 2017 y revisiones posteriores). Principiantes progresan con 8 a 12. Subir el volumen de forma gradual a lo largo del mesociclo y recortarlo en el deload. Palabras clave: volumen series semana mev mav mrv.$$,$$Schoenfeld et al. 2017 (meta-análisis dosis-respuesta de volumen)$$,'revisar',false),
($$hipertrofia$$,$$MEV, MAV y MRV$$,$$Son heurísticos, no leyes. MEV (volumen mínimo efectivo) ronda 6-10 series/semana, MAV (productivo) 10-20 y MRV (máximo recuperable) 20 o más, y varían por músculo, historia y recuperación. Un atleta asistido tolera más, sobre todo en el techo. Si el rendimiento cae dos o más sesiones seguidas, se está en o sobre el MRV. Palabras clave: mev mav mrv landmarks volumen.$$,$$consenso general$$,'revisar',false),
($$hipertrofia$$,$$Cercanía al fallo y RIR$$,$$La hipertrofia ocurre con series que se acercan al fallo: 0 a 3 repeticiones en reserva. No hace falta llegar al fallo en todas las series; en básicos pesados conviene dejar 1-3 RIR y reservar el fallo para aislamientos y la última serie. Los principiantes subestiman su RIR; es más preciso cerca del fallo y en ejercicios simples. Palabras clave: rir fallo cercania intensidad.$$,$$consenso general$$,'revisar',false),
($$hipertrofia$$,$$Rango de repeticiones$$,$$Con series cercanas al fallo, de 5 a 30 repeticiones producen hipertrofia comparable (Schoenfeld 2017, Lasevicius 2018). El rango práctico de 6-12 en básicos y 10-20 en aislamientos equilibra fatiga, técnica y tiempo. Las series muy largas (>30) o muy pesadas (1-3) son menos eficientes para músculo. Palabras clave: repeticiones rango carga reps.$$,$$Schoenfeld 2017; Lasevicius 2018$$,'revisar',false),
($$hipertrofia$$,$$Frecuencia por músculo$$,$$Con el volumen semanal igualado, la frecuencia importa menos que el volumen total, pero repartir en 2-3 estímulos por músculo y semana mejora la calidad de las series y reduce la fatiga por sesión cuando el volumen es alto. Una vez por semana solo es razonable con volumen bajo. Palabras clave: frecuencia split semana.$$,$$consenso general$$,'revisar',false),
($$hipertrofia$$,$$Descansos entre series$$,$$En compuestos, 2 a 3 minutos permiten más repeticiones en las series siguientes y mejor hipertrofia que 1 minuto (Schoenfeld 2016). En aislamientos sirven 60-90 segundos. Descansar menos de lo necesario solo para ahorrar tiempo recorta el volumen real. Palabras clave: descanso rest pausa.$$,$$Schoenfeld 2016$$,'revisar',false),
($$hipertrofia$$,$$Tempo y rango de movimiento$$,$$Excéntrico controlado de 2-3 s, sin rebotes, y recorrido completo. El tempo extremadamente lento no ha mostrado ventaja. Entrenar el músculo en posición estirada (press inclinado, extensión de tríceps sobre la cabeza, curl inclinado, pantorrilla con estiramiento completo) tiene evidencia creciente de mayor hipertrofia; las parciales en la zona estirada son una opción al final del ejercicio. Palabras clave: tempo excentrico rango estiramiento parciales.$$,$$consenso general$$,'revisar',false),
($$hipertrofia$$,$$Sobrecarga progresiva y doble progresión$$,$$Método base: trabajar un rango (ej. 8-12). Cuando todas las series llegan al tope con el RIR objetivo, subir la carga ~2,5% en tren superior y ~5% en tren inferior y volver al piso del rango; si no, mantener carga y buscar +1 repetición. Dos sesiones seguidas bajo el piso: bajar ~5%. La progresión debe ser medible semana a semana. Palabras clave: progresion sobrecarga doble carga.$$,$$consenso general$$,'revisar',false),
($$hipertrofia$$,$$Deload$$,$$Cada 4 a 8 semanas o cuando aparezcan señales: rendimiento a la baja en 2+ sesiones, sueño malo, dolor articular, falta de motivación. Reducir el volumen ~40-50% manteniendo carga moderada y técnica. Un deload planificado evita un parón forzado. Palabras clave: deload descarga fatiga.$$,$$consenso general$$,'revisar',false),
($$hipertrofia$$,$$Checklist de estancamiento$$,$$Antes de cambiar la rutina revisar en orden: adherencia, energía (¿come en el nivel deseado?), sueño, estrés, honestidad del RIR, técnica/rango, volumen (¿bajo el MEV o sobre el MRV?), y tiempo suficiente (mínimo 3-4 semanas con el mismo estímulo). Recién entonces variar ejercicio, volumen o frecuencia. Palabras clave: estancamiento plateau diagnostico.$$,$$consenso general$$,'revisar',false),
($$hipertrofia$$,$$Técnicas de intensidad$$,$$Drop sets, rest-pause, myo-reps, clusters y superseries ahorran tiempo y suben la fatiga por unidad de estímulo; con volumen igualado no son superiores a series tradicionales. Se dosifican: casi siempre en aislamientos y al final del ejercicio, 1-2 por sesión y no en todas las semanas del mesociclo. Palabras clave: drop restpause myo cluster superserie intensidad.$$,$$consenso general$$,'revisar',false),
($$hipertrofia$$,$$Principiantes$$,$$Priorizar técnica, adherencia y progresión simple. 8-12 series por músculo y semana, 2-3 sesiones semanales de cuerpo completo o torso-pierna, 2-3 RIR, subir carga cada semana. La mayoría de la mejora inicial viene de aprender el movimiento. Palabras clave: principiante novato inicio.$$,$$consenso general$$,'revisar',false),
($$hipertrofia$$,$$Orden de ejercicios y puntos débiles$$,$$Los músculos prioritarios y los ejercicios más demandantes van primero en la sesión. Para un punto débil: subir entre 30% y 50% su volumen durante 1-2 mesociclos mientras el resto se mantiene (especialización), y añadir una sesión extra solo si la recuperación lo permite. Palabras clave: orden prioridad punto debil especializacion.$$,$$consenso general$$,'revisar',false),
($$hipertrofia$$,$$Calentamiento y series de aproximación$$,$$Un par de minutos de movilidad/cardio suave y luego 2-3 series de aproximación en el primer básico (aprox. 50%, 70%, 85% del peso de trabajo, repeticiones decrecientes) sin llegar a fatiga. Los ejercicios siguientes necesitan 1 aproximación o ninguna. Palabras clave: calentamiento aproximacion warmup.$$,$$consenso general$$,'revisar',false),
($$hipertrofia$$,$$Mesociclo típico$$,$$4 a 8 semanas: semana 1 con ~3 RIR, y se acerca al fallo cada semana (3→2→1→0 en aislamientos), con series añadidas de forma gradual, y la última semana de deload. Al terminar, reevaluar fotos, medidas, fuerza y recuperación antes de empezar el siguiente. Palabras clave: mesociclo periodizacion bloque semanas.$$,$$consenso general$$,'revisar',false),
($$hipertrofia$$,$$Splits comunes$$,$$Cuerpo completo 3x (principiantes), torso-pierna 4x, push-pull-legs 5-6x, híbridos. Para igual volumen son equivalentes; elegir el que el atleta pueda sostener y que dé 2 estímulos semanales por músculo. Evitar entrenar el mismo músculo grande dos días seguidos con alta fatiga. Palabras clave: split ppl torso pierna frecuencia.$$,$$consenso general$$,'revisar',false),
($$fuerza$$,$$Estimar 1RM y equivalencias$$,$$Epley: 1RM ≈ peso × (1 + reps/30). Brzycki: peso × 36/(37 − reps). Son fiables hasta ~10 repeticiones; más allá sobreestiman. Equivalencia aproximada de % del 1RM: 5 reps ≈ 87%, 8 ≈ 80%, 10 ≈ 75%, 12 ≈ 70%, 15 ≈ 65%. Es una guía, no una ley: varía por ejercicio y persona. Palabras clave: 1rm e1rm epley brzycki porcentaje.$$,$$consenso general$$,'revisar',false),
($$fuerza$$,$$RPE y RIR$$,$$RPE 10 = fallo, 9 = 1 RIR, 8 = 2 RIR, 7 = 3 RIR. Para hipertrofia se usa sobre todo RIR 0-3. Calibrar el RIR con series al fallo ocasionales en ejercicios seguros (máquinas y poleas) mejora la precisión. Palabras clave: rpe rir autoregulacion.$$,$$consenso general$$,'revisar',false),
($$fuerza$$,$$Fuerza máxima y culturismo$$,$$Subir la fuerza en rangos de 5-12 repeticiones es el mejor indicador práctico de progreso en hipertrofia. Los PRs de 1RM no son necesarios en un programa de físico; las repeticiones adicionales con la misma carga y técnica sí. Palabras clave: fuerza pr progreso.$$,$$consenso general$$,'revisar',false),
($$nutricion$$,$$Proteína$$,$$1,6 a 2,2 g/kg de peso corporal al día maximizan la ganancia muscular (meta-análisis de Morton 2018). En déficit o prep de competencia se sube a 2,2-3,1 g/kg de masa magra para conservar músculo (Helms 2014). El total diario importa más que el timing; repartir en 3-5 comidas con ~0,3-0,4 g/kg por comida es práctico. Palabras clave: proteina g/kg comidas.$$,$$Morton et al. 2018; Helms et al. 2014$$,'revisar',false),
($$nutricion$$,$$Fase de volumen (superávit)$$,$$Un superávit moderado del 5 al 10% sobre mantenimiento (10-20% en principiantes) basta. Ritmo orientativo de ganancia de peso: 0,25-0,5% del peso corporal por semana en avanzados, hasta ~1% en principiantes. Más rápido añade sobre todo grasa. Ajustar por la tendencia semanal, no por un día. Palabras clave: volumen superavit calorias subir peso.$$,$$consenso general$$,'revisar',false),
($$nutricion$$,$$Fase de definición (déficit)$$,$$Pérdida de peso de 0,5 a 1% del peso corporal por semana conserva más músculo que ritmos mayores. Proteína alta, entrenamiento pesado mantenido y volumen sin recortes grandes. Si el peso no baja en 2 semanas con adherencia confirmada, ajustar 150-250 kcal o sumar pasos antes de recortar más comida. Palabras clave: definicion deficit bajar peso corte.$$,$$consenso general$$,'revisar',false),
($$nutricion$$,$$Grasas y carbohidratos$$,$$Grasas: no bajar de ~0,6-1 g/kg ni de ~20% de las kcal en períodos largos; en prep extrema ≥15% con vigilancia de salud hormonal. Carbohidratos: el resto de las calorías; 3 a 7 g/kg según volumen de entrenamiento y fase, repartidos alrededor del entrenamiento si el atleta rinde mejor así. Palabras clave: grasas carbohidratos carbos macros.$$,$$consenso general$$,'revisar',false),
($$nutricion$$,$$Ajustar calorías con datos reales$$,$$Usar el promedio de 7 días del peso corporal y comparar dos semanas. Registros de calorías tienen 10-20% de error (apps como MyFitnessPal y porciones a ojo), por eso la tendencia del peso manda. Cambios de ±150-250 kcal por vez; cambiar una variable a la vez. Palabras clave: ajuste calorias peso tendencia myfitnesspal.$$,$$consenso general$$,'revisar',false),
($$nutricion$$,$$Diet breaks y refeeds$$,$$En dietas largas, pausas de 1-2 semanas en mantenimiento cada 6-12 semanas (estudio MATADOR, Byrne 2018) mejoran la pérdida de grasa y la adherencia. Un refeed corto (1-2 días con más carbohidratos) ayuda a la adherencia y el entrenamiento; su efecto hormonal es modesto. Palabras clave: refeed diet break pausa adherencia.$$,$$Byrne et al. 2018 (MATADOR)$$,'revisar',false),
($$suplementos$$,$$Creatina$$,$$Monohidrato 3 a 5 g/día, todos los días, sin fase de carga necesaria. Es el suplemento con mayor respaldo para fuerza y masa muscular, y es seguro en personas sanas. Puede subir 1-2 kg de peso por agua intracelular; no es retención dañina. Palabras clave: creatina suplemento.$$,$$consenso general$$,'revisar',false),
($$suplementos$$,$$Cafeína$$,$$3 a 6 mg/kg unos 30-60 min antes de entrenar mejora rendimiento. Evitar en las 8 horas previas al sueño. Dosis altas diarias generan tolerancia; ciclar o reducir en fases de estrés o mal sueño. Palabras clave: cafeina preentreno.$$,$$consenso general$$,'revisar',false),
($$suplementos$$,$$Otros suplementos$$,$$Con respaldo razonable: proteína en polvo (comodidad), beta-alanina 3,2-6,4 g/día (esfuerzos de 1-4 min; hormigueo normal), citrulina 6-8 g preentreno, omega-3 1-2 g EPA+DHA, vitamina D si hay déficit. Poco o ninguno: BCAA con proteína suficiente, boosters de testosterona, quemadores de grasa, glutamina. Palabras clave: beta alanina citrulina omega vitamina bcaa.$$,$$consenso general$$,'revisar',false),
($$nutricion$$,$$Hidratación y sodio$$,$$Alrededor de 30-40 ml/kg al día, más en calor o sudoración alta; la orina clara-amarilla es una guía simple. El sodio no se recorta de forma agresiva en ningún caso salvo indicación médica; mantener estable es mejor que manipularlo bruscamente. Palabras clave: agua sodio hidratacion.$$,$$consenso general$$,'revisar',false),
($$nutricion$$,$$Timing peri-entrenamiento$$,$$La ventana anabólica es amplia (varias horas). Una comida con proteína y carbohidratos 1-3 horas antes y otra después del entrenamiento es suficiente. Entrenar en ayunas es viable pero rinde peor en sesiones largas o pesadas si el atleta se siente sin energía. Palabras clave: timing preentreno postentreno ayuno.$$,$$consenso general$$,'revisar',false),
($$nutricion$$,$$Fibra y micronutrientes$$,$$25-40 g de fibra al día, 2-3 porciones de verduras y 1-2 de frutas, fuentes variadas de proteína. En déficit prolongado revisar hierro, vitamina D, magnesio y zinc con exámenes de sangre antes de suplementar. Palabras clave: fibra verduras micronutrientes.$$,$$consenso general$$,'revisar',false),
($$recuperacion$$,$$Sueño y estrés$$,$$7 a 9 horas de sueño. Dormir poco reduce el rendimiento, la recuperación y la adherencia al plan, y empeora el hambre. Es la primera variable a revisar cuando la fuerza cae o aparece fatiga. Palabras clave: sueno descanso estres.$$,$$consenso general$$,'revisar',false),
($$recuperacion$$,$$Leer recuperación (WHOOP/HRV)$$,$$Usar tendencias de 7+ días, no un valor suelto. Recuperación o HRV por debajo de la línea base 3 o más días, sumado a menor rendimiento o mal sueño, justifica bajar volumen o intensidad. Un día bajo aislado no cambia el plan. Palabras clave: whoop hrv recuperacion wearable.$$,$$consenso general$$,'revisar',false),
($$recuperacion$$,$$Cardio y pasos$$,$$En volumen: 6-8k pasos y 1-2 sesiones suaves de 20-30 min para salud. En definición: subir pasos (8-12k) antes de añadir cardio, y 2-4 sesiones de 20-40 min de baja intensidad según necesidad. Evitar cardio intenso justo antes de piernas pesadas. Palabras clave: cardio pasos liss hiit.$$,$$consenso general$$,'revisar',false),
($$competencia$$,$$Categorías de físico$$,$$Men's Open (máximo desarrollo), Classic Physique (proporciones estéticas con límites de peso por altura), Men's Physique (shorts, sin énfasis en piernas), Bikini, Wellness, Figure y Women's Physique. Los límites de peso y la ropa de posado varían por federación y año: confirmar la tabla vigente de la federación antes de fijar metas de peso. Palabras clave: categoria open classic physique bikini wellness.$$,$$consenso general$$,'revisar',false),
($$competencia$$,$$Timeline de preparación$$,$$16 a 24 semanas según el punto de partida y la categoría, con pérdida de 0,5-1% del peso por semana, proteína alta, entrenamiento pesado conservado y fotos/medidas semanales. Planificar la salida (reverse) desde el inicio. Evaluar condición cada 1-2 semanas y ajustar por tendencia. Palabras clave: prep competencia semanas timeline.$$,$$consenso general$$,'revisar',false),
($$competencia$$,$$Peak week$$,$$La evidencia sobre manipular agua, sodio y carbohidratos es limitada y muy individual. Lo razonable: no cambiar nada drástico, subir carbohidratos de forma moderada los últimos días si el atleta ya lo probó en la prep, mantener el agua y el sodio estables, y ensayar el protocolo semanas antes. La deshidratación agresiva y los diuréticos son un riesgo médico y no se programan. Palabras clave: peak week carbos agua sodio.$$,$$consenso general$$,'revisar',false),
($$competencia$$,$$Posing$$,$$Practicar poses obligatorias 10-15 min al día durante las últimas 8-12 semanas, con grabación para corregir. Las poses isométricas también cansan: incluirlas ya en la prep, no solo la semana del show. Palabras clave: posing poses show.$$,$$consenso general$$,'revisar',false),
($$competencia$$,$$Salida de la prep (reverse)$$,$$Subir calorías de forma gradual, 50-150 kcal por semana, controlando peso, hambre y entrenamiento. Mantener proteína y pasos, bajar cardio de a poco. Una salida desordenada genera rebote de grasa y mala relación con la comida. Palabras clave: reverse salida postshow rebote.$$,$$consenso general$$,'revisar',false),
($$competencia$$,$$Riesgos de la prep$$,$$Señales para derivar a un profesional: pérdida de menstruación, mareos o desmayos, frío extremo, arritmias, pensamientos obsesivos con la comida, atracones, aislamiento social, insomnio persistente. La salud va antes que la condición del día del show. Palabras clave: riesgos salud red-s alimentacion.$$,$$consenso general$$,'revisar',false),
($$tecnica$$,$$Sentadilla$$,$$Apoyo estable de pies a ancho de hombros o algo mayor, rodillas siguen la línea de los pies, tronco firme con respiración y bracing, profundidad hasta donde se mantenga la espalda neutra. Para hipertrofia sirven variantes (barra alta, goblet, hack, prensa) si el patrón original molesta. Palabras clave: sentadilla squat tecnica.$$,$$consenso general$$,'revisar',false),
($$tecnica$$,$$Peso muerto y rumano$$,$$Espalda neutra, barra pegada al cuerpo, bisagra de cadera. En el peso muerto rumano las rodillas se flexionan poco y la bajada llega hasta sentir tensión en isquios, sin redondear la lumbar. El peso muerto convencional es muy fatigante: dosificarlo si se entrenan piernas pesado. Palabras clave: peso muerto rumano deadlift tecnica.$$,$$consenso general$$,'revisar',false),
($$tecnica$$,$$Press banca y pecho$$,$$Escápulas retraídas y apoyadas, pies firmes, barra baja a la parte media del pecho con codos ~45-70° del tronco y empuje controlado. En inclinado 30° prioriza pecho superior. Aperturas y cruces en polea trabajan el pecho en estiramiento con menos riesgo de hombro. Palabras clave: press banca pecho tecnica.$$,$$consenso general$$,'revisar',false),
($$tecnica$$,$$Hombro y deltoides$$,$$Elevaciones laterales con ligera inclinación y codos suaves; polea da tensión constante. Press militar con core firme y sin hiperextender la lumbar. Para deltoides posteriores: face pull o pájaros sin encoger el cuello. Palabras clave: hombro deltoides laterales press militar.$$,$$consenso general$$,'revisar',false),
($$tecnica$$,$$Espalda$$,$$Dominadas y jalones: iniciar con depresión escapular y llevar codos hacia abajo; agarres distintos reparten el estímulo. Remos: pecho estable, tirar hacia la cadera para dorsal, hacia el torso alto para espalda media. Evitar balanceo del tronco que le quita tensión al músculo. Palabras clave: espalda dorsal remo dominada jalon.$$,$$consenso general$$,'revisar',false),
($$tecnica$$,$$Brazos$$,$$Bíceps: curl inclinado trabaja el estiramiento, curl predicador la parte corta; evitar balanceo. Tríceps: extensiones sobre la cabeza trabajan la cabeza larga en estiramiento; empujes en polea para la carga. Codos fijos. Palabras clave: biceps triceps curl extension brazos.$$,$$consenso general$$,'revisar',false),
($$tecnica$$,$$Piernas$$,$$Cuádriceps: prensa, hack, sentadilla, extensión; profundidad amplia. Isquios: curl tumbado/sentado + bisagra (RDL). Glúteo: hip thrust con pausa arriba y mentón recogido. Pantorrilla: pausa abajo en estiramiento completo y arriba en contracción, 10-15 reps con control. Palabras clave: piernas cuadriceps isquios gluteo pantorrilla.$$,$$consenso general$$,'revisar',false),
($$tecnica$$,$$Abdomen y core$$,$$Flexión de tronco con control (crunch en polea, rueda), anti-extensión (plancha) y anti-rotación (Pallof). Se entrena como cualquier músculo: carga progresiva, 2-3 veces por semana, series cerca del fallo. Palabras clave: abdomen core abs crunch plancha.$$,$$consenso general$$,'revisar',false),
($$lesiones$$,$$Dolor: cuándo parar y derivar$$,$$Dolor agudo, punzante o que aumenta durante la serie: parar. Derivar al médico: dolor nocturno o en reposo, hormigueo o pérdida de fuerza, inflamación marcada, dolor torácico, mareo, bloqueo articular, dolor que no mejora en 1-2 semanas. El dolor muscular tardío (DOMS) es difuso y mejora en 48-72 h; el dolor articular o tendinoso puntual no lo es. Palabras clave: dolor lesion alarma medico.$$,$$consenso general$$,'revisar',false),
($$lesiones$$,$$Modificar el entrenamiento con molestias$$,$$No suele ser necesario parar: sustituir el ejercicio por una variante sin dolor, reducir rango o carga, cambiar agarre/ángulo y mantener el resto. La molestia debe ser leve (≤3/10), no empeorar durante la sesión y estar estable o mejor a las 24 h. Palabras clave: molestia lesion modificar sustituir.$$,$$consenso general$$,'revisar',false),
($$lesiones$$,$$Tendinopatías por sobreuso$$,$$Más frecuentes en codo, hombro, rodilla y Aquiles, sobre todo cuando la fuerza sube más rápido que el tendón se adapta. Manejo general: bajar la carga de la zona, usar isométricos y cargas lentas progresivas, no dejar de mover. Si persiste, fisioterapeuta. Palabras clave: tendon tendinitis codo rodilla hombro.$$,$$consenso general$$,'revisar',false),
($$lesiones$$,$$Lumbar$$,$$Molestia lumbar mecánica: reducir flexión cargada, sustituir peso muerto/remo con barra por variantes con apoyo (prensa, remo en máquina), mejorar bracing y caminar. Dolor irradiado a la pierna, debilidad o alteraciones de esfínteres: urgencia médica. Palabras clave: lumbar espalda baja dolor.$$,$$consenso general$$,'revisar',false),
($$seguridad$$,$$Sustancias y atletas asistidos$$,$$La IA programa entrenamiento y nutrición también para atletas asistidos, pero no receta, no dosifica ni arma protocolos de esteroides, hormonas, SARMs ni diuréticos: eso es decisión de un médico. Sí puede explicar riesgos generales y la importancia del control médico periódico (hemograma/hematocrito, lípidos, presión arterial, función hepática y renal, hormonas) y ajustar entrenamiento y nutrición para ese perfil. Palabras clave: esteroides asistido ciclo sustancias medico.$$,$$consenso general$$,'revisar',false),
($$seguridad$$,$$Programar para atletas asistidos$$,$$Toleran más volumen y frecuencia y recuperan más rápido, pero tendones y articulaciones no reciben el mismo beneficio: la progresión de carga en básicos pesados debe ser más prudente que la del músculo. Deloads siguen siendo necesarios. Vigilar presión, retención de líquido y hematocrito con el médico. Palabras clave: asistido ciclo volumen tendones.$$,$$consenso general$$,'revisar',false),
($$app$$,$$Progresión automática de FORJA$$,$$La app calcula el peso y las reps a buscar hoy con doble progresión y RIR: sube carga (2,5% superior / 5% inferior; doble si el RIR superó el objetivo en 2+) cuando todas las series llegan al tope; si no, mantiene y busca +1 rep; baja ~5% tras dos sesiones bajo el piso; ~5-10% tras semanas sin hacerlo o en descarga. Valores exactos, sin redondear a discos. Cada tipo de serie usa su propia referencia (top, back-off, drop, rest-pause, cluster, AMRAP). Palabras clave: app progresion sugerencia peso.$$,$$consenso general$$,'revisar',false),
($$app$$,$$Tipos de serie$$,$$Aproximación (calentamiento), normal, top set (la más pesada), back-off (baja carga tras el top), drop (reducir peso sin descanso), rest-pause (pausas cortas y más reps), AMRAP (máximo de reps), cluster (mini-bloques con micro pausas), VMA/iso (isométrico), PFI y density. Se usan como técnica de intensidad dosificada. Palabras clave: app series tipos drop restpause.$$,$$consenso general$$,'revisar',false),
($$app$$,$$Qué puede cambiar la IA en la app$$,$$El alumno solo pregunta y puede proponer cambios; el coach los aprueba y se aplican al plan. Nada se modifica solo. Las propuestas incluyen el motivo y los datos que las respaldan. Palabras clave: app permisos propuestas coach.$$,$$consenso general$$,'revisar',false)
